const { mc, qcm, vf, glisser, entourer, ordre, relier, classer, surligner, b, lecon } = require('../dsl');

// Socle partagé : ENSEA AS, INFJ et ENS. Plans proposés = exemples de méthode,
// jamais corrigés officiels ni formats imposés à tous les concours.
const dissertation = {
  code: 'ENSEA-AS-OG', matiere: 'Français',
  titre: 'Ordre général : la dissertation',
  resume: 'Passer d’un sujet à une réponse justifiée : analyse, problématique, plan et rédaction.',
  notions: [
    { code: 'SUJET', libelle: 'Consigne, termes et limites du sujet' },
    { code: 'PROBLEMATIQUE', libelle: 'Question directrice et difficulté à résoudre' },
    { code: 'ARGUMENTER', libelle: 'Arguments, exemples et objections' },
    { code: 'PLAN', libelle: 'Organisation de la démonstration' },
    { code: 'REDACTION', libelle: 'Introduction, paragraphes, transitions et conclusion' },
    { code: 'REVISION', libelle: 'Gestion du temps et relecture' },
  ],
  lecons: [
    lecon('ENSEA-AS-OG-L1', 'Reconnaître la tâche et choisir un sujet', 3, [
      b.texte('Tu vas comprendre ce qu’est une **dissertation** : un texte organisé qui répond à une question en donnant des raisons et des exemples. Elle permet de défendre une réponse que le lecteur peut examiner.'),
      b.texte('Le **sujet** est l’énoncé proposé ; la **consigne** précise l’action attendue. « Expliquez » demande de rendre une idée compréhensible. « Discutez » ou « Qu’en pensez-vous ? » demande d’examiner sa valeur et ses limites avant de répondre.'),
      b.exemple('Une question précise', '« La lecture peut-elle favoriser l’autonomie ? » demande un lien entre lecture et capacité à agir ou penser par soi-même. Raconter tous les livres lus ne répond pas à cette question.'),
      b.exemple('Choisir entre plusieurs sujets', 'Si trois sujets sont proposés au choix, reformule chacun en une phrase. Pour chaque sujet compris, cherche deux raisons, un exemple et une difficulté. Choisis celui pour lequel tes connaissances permettent une discussion précise.'),
      b.piege('Une opinion personnelle sans justification ne forme pas une dissertation. Une citation connue ne remplace pas non plus une explication.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L1-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['SUJET'], consigne: '« Qu’en pensez-vous ? » demande surtout…', options: ['Une réponse argumentée qui examine aussi les limites', 'Un oui ou un non sans justification', 'Un résumé de la citation uniquement'], bonne: 0, explication: 'Il faut comprendre la proposition, la discuter puis prendre position avec des raisons. Le résumé seul prépare éventuellement le travail mais ne constitue pas la réponse.', miniCours: mc('La dissertation', 'La dissertation construit une réponse justifiée à la question posée.', 'Répondre en raisonnant.') })),
      b.recap(['Identifier l’action demandée.', 'Choisir selon sa compréhension et ses arguments.', 'Répondre à une question précise.']),
    ]),
    lecon('ENSEA-AS-OG-L2', 'Définir les mots et délimiter la question', 4, [
      b.texte('Tu vas analyser les mots du sujet pour éviter le **hors-sujet** : traiter une autre question. Définir un terme consiste à préciser le sens qu’il prend ici.'),
      b.liste(['Entourer les mots qui portent le thème et la relation demandée.', 'Relever les limites : lieu, période, groupe concerné.', 'Souligner les mots exigeants : tout, toujours, seulement, nécessairement.'], true),
      b.exemple('Un mot qui change tout', '« Le progrès technique améliore-t-il toujours la vie ? » Progrès technique : nouveaux moyens de produire ou d’agir. Améliorer la vie : rendre les conditions de vie meilleures. « Toujours » oblige à chercher si les avantages sont systématiques.'),
      b.exemple('Deux échelles à respecter', '« Comment améliorer l’accès à l’eau au niveau local et entre les pays ? » exige de distinguer une réponse locale d’une coopération entre États. Ne traiter que les gestes domestiques oublierait la seconde échelle.'),
      b.piege('Une définition sert le raisonnement ; une longue suite de définitions de dictionnaire éloigne de la question. Explique surtout les termes discutables et leurs relations.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L2-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['SUJET'], consigne: 'Dans « L’école suffit-elle à former un citoyen ? », que faut-il examiner ?', options: ['Si l’école peut assurer à elle seule cette formation', 'Si l’école existe', 'Si tous les citoyens deviennent enseignants'], bonne: 0, explication: '« Suffire » signifie être assez à soi seul. Il faut donc examiner l’action de l’école et le rôle éventuel d’autres acteurs.', miniCours: mc('Les mots décisifs', 'Les mots de portée modifient la question : possible, nécessaire, suffisant ou exclusif ne sont pas équivalents.', 'Définir la relation demandée.') })),
      b.recap(['Définir les termes dans leur contexte.', 'Respecter toutes les limites.', 'Examiner les mots de portée.']),
    ]),
    lecon('ENSEA-AS-OG-L3', 'Construire une problématique', 4, [
      b.texte('Tu vas formuler la **problématique** : la question directrice qui met en évidence la difficulté du sujet. Elle guide la réponse au lieu d’annoncer un simple thème.'),
      b.texte('Cherche une première réponse plausible, puis ce qui l’empêche d’être entièrement satisfaisante. Cette tension fait apparaître ce qu’il faut résoudre. Si le sujet contient déjà une bonne question, tu peux la préciser sans inventer un autre problème.'),
      b.exemple('D’un thème à une tension', 'Sujet : « L’information rend-elle libre ? » Première idée : être informé aide à choisir. Difficulté : une information trompeuse peut orienter les choix. Question directrice : « À quelles conditions l’information permet-elle de choisir librement plutôt que de subir une influence ? »'),
      b.exemple('Une demande de moyens', 'Sujet : « Comment rendre l’eau accessible à tous ? » Difficulté : la ressource et les moyens sont inégalement répartis. Question possible : « Comment associer aménagements locaux et coopération entre territoires pour assurer un accès équitable ? »'),
      b.piege('« Nous parlerons de l’eau » annonce un thème, pas une difficulté. À l’inverse, ne force pas une opposition oui/non quand le sujet demande des moyens complémentaires.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L3-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['PROBLEMATIQUE'], consigne: 'Quelle problématique traite « Le numérique réduit-il les inégalités scolaires ? » ?', options: ['À quelles conditions l’accès numérique aide-t-il les élèves sans accroître les écarts de moyens et de maîtrise ?', 'Qu’est-ce qu’un ordinateur ?', 'Pourquoi faut-il raconter toute l’histoire de l’école ?'], bonne: 0, explication: 'La première question relie le numérique aux inégalités et met en tension une aide possible et un risque d’écart. Les autres isolent un terme ou élargissent abusivement le sujet.', miniCours: mc('La question directrice', 'Une problématique reste dans le sujet et explicite ce qui rend sa réponse difficile.', 'Une difficulté précise à résoudre.') })),
      b.recap(['Partir de la question du sujet.', 'Chercher une difficulté réelle.', 'Formuler une question qui guidera le devoir.']),
    ]),
    lecon('ENSEA-AS-OG-L4', 'Construire un argument avec un exemple', 4, [
      b.texte('Tu vas justifier une idée. Un **argument** est une raison qui soutient une réponse ; un **exemple** est un cas concret qui permet de comprendre cette raison.'),
      b.texte('Au brouillon, écris l’idée puis demande « Pourquoi ? » et « Comment cela agit-il ? ». Ajoute un exemple et explique ce qu’il montre. Une **objection** est une raison qui conteste une affirmation ; l’examiner permet d’en préciser les limites.'),
      b.exemple('Un mécanisme expliqué', 'Idée : une bibliothèque favorise l’accès au savoir. Pourquoi ? Le prêt évite de devoir acheter chaque livre. Exemple hypothétique : un élève emprunte un manuel indisponible chez lui. L’exemple montre comment le prêt réduit un obstacle financier.'),
      b.exemple('Une limite utile', 'Objection : un bâtiment éloigné reste difficile à fréquenter. Réponse : le prêt aide, mais son effet dépend aussi de la proximité ou d’une desserte mobile. L’argument devient conditionnel et plus précis.'),
      b.piege('Un cas isolé ne prouve pas que tous les élèves progressent. N’invente ni statistique, ni citation, ni événement : un exemple imaginé doit être présenté comme hypothétique.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L4-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['ARGUMENTER'], consigne: 'Quel énoncé explique un mécanisme ?', options: ['Le prêt évite l’achat de chaque livre et réduit ainsi un obstacle financier.', 'La bibliothèque est formidable.', 'Tout le monde sait que lire est bien.'], bonne: 0, explication: 'La première phrase relie une action à un effet par une raison explicite. Les deux autres sont des jugements sans explication.', miniCours: mc('Justifier', 'Un argument explique pourquoi une idée répond au sujet. L’exemple rend cette explication concrète.', 'Idée, raison, illustration, lien au sujet.') })),
      b.recap(['Expliquer pourquoi et comment.', 'Commenter ce que montre l’exemple.', 'Examiner une limite sans caricaturer.']),
    ]),
    lecon('ENSEA-AS-OG-L5', 'Organiser un plan qui répond au sujet', 4, [
      b.texte('Tu vas construire un **plan** : l’ordre des grandes étapes de ta réponse. Une partie regroupe plusieurs arguments qui défendent une même idée centrale.'),
      b.texte('Classe tes arguments par fonction, puis formule une réponse pour chaque groupe. Vérifie que chaque partie apporte une étape nouvelle et que leur ensemble répond à toute la question. Le nombre de parties dépend du sujet et des consignes, pas d’une recette universelle.'),
      b.exemple('Discuter une affirmation', '« Le numérique suffit-il à apprendre ? » Plan possible : I. Il élargit les ressources disponibles. II. Ces ressources ne deviennent des apprentissages qu’avec des conditions de maîtrise et d’accompagnement. Les deux parties construisent une réponse au mot « suffit ».'),
      b.exemple('Répondre à une demande de moyens', '« Comment améliorer l’accès à l’eau localement et entre pays ? » Plan possible : I. Réduire les obstacles locaux d’accès et d’usage. II. Organiser la coopération pour les ressources partagées. Chaque partie traite une échelle explicitement demandée.'),
      b.piege('« Avantages / inconvénients » convient à certains sujets, pas à tous. « Oui / non » sans réponse finale produit une contradiction, pas une démonstration.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L5-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['PLAN'], consigne: 'Quelle vérification faire avant de garder un plan ?', options: ['Chaque partie contribue à la réponse et l’ensemble couvre la question.', 'Toutes les parties racontent le même exemple.', 'Le plan a trois parties, quel que soit le sujet.'], bonne: 0, explication: 'Le plan est utile s’il fait progresser la réponse sans oublier une dimension demandée. Un nombre fixe de parties ou des répétitions ne garantissent aucune pertinence.', miniCours: mc('Organiser une démonstration', 'Les parties sont des étapes complémentaires d’une réponse, choisies à partir de la question et des arguments.', 'Le sujet commande le plan.') })),
      b.recap(['Grouper les arguments par idée.', 'Donner une fonction à chaque partie.', 'Vérifier la couverture du sujet.']),
    ]),
    lecon('ENSEA-AS-OG-L6', 'Rédiger une introduction utile', 4, [
      b.texte('Tu vas rédiger l’**introduction**, le début du devoir qui conduit le lecteur du sujet à la question puis au parcours de réponse. Prépare d’abord ton plan : tu pourras ainsi annoncer celui que tu suivras réellement.'),
      b.liste(['Entrer dans le sujet par un constat précis ou directement par la question.', 'Définir les termes utiles et faire apparaître la difficulté.', 'Formuler la problématique.', 'Annoncer les étapes du plan.'], true),
      b.exemple('Un début ciblé', 'Sujet d’entraînement : « Le numérique suffit-il à apprendre ? » Début possible : « Consulter un cours sur un écran donne accès à une ressource. Apprendre suppose cependant de la comprendre et de savoir la réutiliser. » Ces phrases posent déjà la distinction utile.'),
      b.exemple('Question et annonce', 'Suite possible : « Dans quelles conditions les ressources numériques deviennent-elles de véritables apprentissages ? Nous examinerons d’abord leur apport, puis les conditions de maîtrise et d’accompagnement nécessaires. » L’annonce correspond au plan de L5.'),
      b.piege('Évite « Depuis la nuit des temps… » et les citations dont tu ignores la formulation exacte. Une entrée directe et pertinente vaut mieux qu’une accroche inventée.'),
      b.question(ordre({ code: 'ENSEA-AS-OG-L6-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['REDACTION'], mode: 'exact', consigne: 'Ordonne cette introduction selon la méthode proposée.', elements: ['Présenter les termes et la difficulté du sujet', 'Formuler la question directrice', 'Annoncer les étapes de réponse'], explication: 'Le lecteur doit comprendre le sujet et sa difficulté avant la question. L’annonce du plan vient ensuite montrer comment le devoir y répondra.', miniCours: mc('Introduire', 'L’introduction prépare une question précise puis le parcours qui permettra d’y répondre.', 'Sujet, problème, parcours.') })),
      b.recap(['Entrer précisément dans le sujet.', 'Expliquer la difficulté.', 'Annoncer le plan réellement suivi.']),
    ]),
    lecon('ENSEA-AS-OG-L7', 'Rédiger un paragraphe et une transition', 4, [
      b.texte('Tu vas transformer ton plan en raisonnement rédigé. Un **paragraphe** développe une idée principale. Une **transition** résume ce qui vient d’être établi et explique pourquoi l’étape suivante est nécessaire.'),
      b.texte('Construis le paragraphe dans cet ordre : idée liée au sujet, raison expliquée, exemple commenté, résultat pour la réponse. Ce canevas aide à développer un argument ; il ne doit pas devenir une formule répétée mot pour mot.'),
      b.exemple('Paragraphe possible', '« Le numérique peut élargir l’accès aux exercices. Un même support permet de consulter plusieurs activités sans disposer de tous les manuels. Imaginons un élève utilisant une ressource téléchargée pour reprendre un exercice : il dispose alors d’une occasion supplémentaire de s’entraîner. Cet accès crée une possibilité d’apprentissage, dont l’usage reste à examiner. »'),
      b.exemple('Transition vers la limite', '« Les ressources numériques multiplient donc les occasions de travailler. Encore faut-il pouvoir les comprendre et les utiliser : l’accès ne garantit pas à lui seul l’apprentissage. » Le bilan mène à la seconde partie de L5.'),
      b.piege('Un connecteur comme « ensuite » ne remplace pas le lien entre les idées. À l’ENSEA, les recommandations du jury 2026 demandent une dissertation rédigée sans titres de parties apparents ; garde les intitulés au brouillon et rends le plan visible par les paragraphes et transitions.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L7-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['REDACTION', 'ARGUMENTER'], consigne: 'Quelle transition fait progresser la réponse ?', options: ['L’accès s’élargit ; examinons maintenant les conditions nécessaires pour en tirer un apprentissage.', 'Deuxièmement : autre chose.', 'Nous avons fini, voici une nouvelle liste.'], bonne: 0, explication: 'La première phrase reprend le résultat acquis puis en indique la limite. Elle explique ainsi le passage de l’accès aux conditions d’apprentissage.', miniCours: mc('Enchaîner', 'Une transition relie un bilan à une nouvelle étape nécessaire du raisonnement.', 'Bilan puis besoin de poursuivre.') })),
      b.recap(['Une idée expliquée par paragraphe.', 'Relier l’exemple à l’argument.', 'Faire progresser la réponse par les transitions.']),
    ]),
    lecon('ENSEA-AS-OG-L8', 'Conclure en répondant vraiment', 3, [
      b.texte('Tu vas rédiger la **conclusion** : la fin du devoir qui répond à la question directrice à partir du raisonnement effectué. Elle ne se limite pas à répéter les titres du plan.'),
      b.texte('Relis ta problématique. Résume en une phrase ce que tes arguments ont permis d’établir, puis formule une réponse précise, éventuellement assortie de conditions. Une ouverture est possible si elle prolonge le résultat ; elle n’est pas une obligation.'),
      b.exemple('Réponse construite', '« Les outils numériques élargissent les ressources, mais ne suffisent pas à apprendre. Leur utilité dépend de la compréhension, de l’entraînement et de l’accompagnement qui permettent de transformer cet accès en savoirs maîtrisés. » Cette conclusion répond à « suffit-il ? ».'),
      b.exemple('Éviter une fausse ouverture', 'Après cette réponse, « Et que penser du sport ? » change arbitrairement de thème. On peut terminer sur la réponse acquise plutôt que chercher une nouvelle question sans lien.'),
      b.piege('N’introduis pas une preuve importante que le développement n’a pas examinée. Le lecteur ne pourrait pas vérifier comment elle soutient la conclusion.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L8-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['REDACTION'], consigne: 'Quelle phrase conclut un raisonnement sur les conditions de l’accès au savoir ?', options: ['L’accès aide, mais son effet dépend aussi des conditions d’usage examinées.', 'Nous avons fait deux parties.', 'Voici enfin un fait nouveau qui change tout.'], bonne: 0, explication: 'La première formule un résultat conditionnel issu de l’analyse. La deuxième décrit seulement l’organisation ; la troisième ouvre une démonstration non menée.', miniCours: mc('Conclure', 'La conclusion formule la réponse obtenue et ses limites à partir des arguments déjà développés.', 'Une réponse fondée.') })),
      b.recap(['Revenir à la problématique.', 'Formuler le résultat de la démonstration.', 'Garder une ouverture seulement si elle est utile.']),
    ]),
    lecon('ENSEA-AS-OG-L9', 'Organiser son temps et relire sa copie', 3, [
      b.texte('Tu vas réserver du temps à chaque tâche pour rendre un devoir complet. Les étapes des leçons précédentes servent de points de contrôle.'),
      b.exemple('Répartition d’entraînement sur 3 heures', 'Choix et analyse : 20 min ; arguments et plan : 30 min ; rédaction : 110 min ; relecture : 20 min. Total : 180 min. C’est une proposition à ajuster après un essai chronométré, pas un barème officiel.'),
      b.texte('La relecture du sens vérifie : ai-je répondu à tous les aspects du sujet ? Le développement suit-il le plan annoncé ? La conclusion répond-elle à la question ? La relecture de langue vérifie ensuite phrases, accords, ponctuation et lisibilité.'),
      b.exemple('Réparer un écart', 'L’introduction promet un volet local et un volet international, mais le développement ne traite que les usages domestiques. Il faut rétablir l’échelle internationale ; retirer seulement son annonce ne réparerait pas l’oubli d’une partie du sujet.'),
      b.piege('Ne passe pas toute l’épreuve au brouillon. Fixe une heure de passage à la rédaction et garde un temps pour une vraie conclusion.'),
      b.question(qcm({ code: 'ENSEA-AS-OG-L9-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['REVISION'], consigne: 'Tu relis une copie : le plan annoncé n’est pas suivi. Que vérifier en premier ?', options: ['La cohérence entre sujet, annonce et développement', 'Seulement les accents', 'Le nombre de citations'], bonne: 0, explication: 'Il faut d’abord savoir si la réponse traite bien le sujet et progresse comme annoncé. Les corrections de langue viennent ensuite compléter ce contrôle du sens.', miniCours: mc('Relire efficacement', 'Contrôle la réponse et sa structure, puis la langue et la présentation.', 'Du sens à la forme.') })),
      b.recap(['Prévoir des repères de temps.', 'Finir le raisonnement et la conclusion.', 'Relire la cohérence puis la langue.']),
    ]),
  ],
  exercices: [
    relier({ code: 'ENSEA-AS-OG-E01', niveau: 1, notions: ['SUJET'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025' }, consigne: 'Relie chaque consigne à la tâche attendue.', paires: [['Expliquez', 'Rendre une idée compréhensible en montrant son sens'], ['Discutez', 'Examiner une proposition et ses limites avant de répondre'], ['Proposez des moyens', 'Présenter des actions justifiées adaptées au problème']], explication: 'Expliquer éclaire un sens ou un mécanisme. Discuter examine la valeur et les limites d’une proposition. Proposer des moyens exige des actions reliées au problème, avec une justification de leur effet attendu.', miniCours: mc('Lire la demande', 'Le verbe de consigne indique la forme du travail. Reformule cette demande avant de chercher tes idées.', 'Adapter la réponse à la tâche.') }),
    surligner({ code: 'ENSEA-AS-OG-E02', niveau: 1, notions: ['SUJET'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Surligne le seul mot qui impose d’examiner le caractère systématique des effets.', segments: [['Le progrès technique ', false], ['améliore-t-il ', false], ['toujours ', true], ['les conditions de vie ?', false]], explication: '« Toujours » étend l’affirmation à tous les cas. Il faut donc examiner les effets favorables, mais aussi les situations où ils manquent ou s’accompagnent de risques.', miniCours: mc('La portée des mots', 'Toujours, seulement et nécessairement modifient l’étendue d’une affirmation. Ne les efface pas dans ta reformulation.', 'Respecter les mots de portée.') }),
    qcm({ code: 'ENSEA-AS-OG-E03', niveau: 1, notions: ['PROBLEMATIQUE'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Sujet : « L’information rend-elle libre ? » Quelle question fait apparaître une difficulté pertinente ?', options: ['Comment l’information peut-elle éclairer les choix sans devenir un moyen de manipulation ?', 'Quels sont tous les journaux du monde ?', 'Comment fabriquer un téléphone ?'], bonne: 0, explication: 'La première question garde le lien entre information et liberté. Elle oppose deux effets possibles pour chercher leurs conditions. Les autres questions isolent des objets voisins sans traiter la relation demandée.', miniCours: mc('Problématiser', 'Fais apparaître une tension qui empêche une réponse immédiate, tout en restant dans les limites du sujet.', 'Une question fidèle et précise.') }),
    classer({ code: 'ENSEA-AS-OG-E04', niveau: 1, notions: ['ARGUMENTER'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Classe les éléments d’un raisonnement sur la bibliothèque.', categories: ['Argument', 'Exemple hypothétique', 'Objection'], cartes: [['Le prêt réduit la nécessité d’acheter chaque livre.', 0], ['Imaginons une élève qui emprunte un manuel absent chez elle.', 1], ['Un bâtiment très éloigné peut rester difficile à fréquenter.', 2]], explication: 'Le prêt et l’achat expliquent un mécanisme : c’est l’argument. L’élève imaginée le rend concret : c’est l’exemple. La distance limite la portée du bénéfice : c’est l’objection à examiner.', miniCours: mc('Raison et illustration', 'L’argument justifie ; l’exemple montre un cas ; l’objection invite à préciser une limite.', 'Distinguer les fonctions.') }),
    ordre({ code: 'ENSEA-AS-OG-E05', niveau: 1, notions: ['REDACTION'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, mode: 'exact', consigne: 'Ordonne ces étapes de l’introduction selon la méthode du cours.', elements: ['Présenter le sujet et préciser les termes utiles', 'Faire apparaître la difficulté et poser la question directrice', 'Annoncer les étapes du plan'], explication: 'Le sens du sujet prépare la difficulté. La question donne ensuite sa direction au devoir. Le plan annoncé montre enfin le parcours qui permettra de répondre.', miniCours: mc('L’introduction', 'L’introduction conduit du sujet au problème puis au parcours de réponse.', 'Faire comprendre avant d’annoncer.') }),
    qcm({ code: 'ENSEA-AS-OG-E06', indice: 'Repère les deux échelles explicitement demandées avant de comparer les plans.', niveau: 2, notions: ['PLAN', 'SUJET'], source: { type: 'annale', organisme: 'ENSEA', annee: 2025, epreuve: 'ISE cycle long / AS — Ordre général, sujet 3', documentId: '6ac272b7316193dda86e43a6' }, consigne: 'Adaptation du sujet ENSEA AS 2025 sur l’accès équitable à l’eau, localement et entre pays : quel plan couvre les deux échelles demandées ?', options: ['I. Aménager et gérer l’accès local ; II. Coopérer pour les ressources partagées entre pays', 'I. Boire davantage ; II. Acheter des bouteilles', 'I. Histoire de toutes les guerres ; II. Biographie d’un dirigeant'], bonne: 0, explication: '(ENSEA AS 2025, Ordre général, sujet 3, adaptation) Le sujet demande de mieux gérer l’eau au niveau local et transnational pour un accès équitable. Le premier plan réserve une étape à chaque échelle ; les autres réduisent le problème aux usages individuels ou s’en éloignent.', miniCours: mc('Couvrir les dimensions du sujet', 'Quand plusieurs échelles sont explicitement demandées, vérifie que le plan et les arguments prennent chacune en charge.', 'Ne pas oublier une dimension.') }),
    qcm({ code: 'ENSEA-AS-OG-E07', niveau: 2, notions: ['PROBLEMATIQUE', 'SUJET'], source: { type: 'annale', organisme: 'ENSEA', annee: 2024, epreuve: 'ISE cycle long / AS — Ordre général, sujet 1', documentId: '6ac272ad316193dda86e438a' }, consigne: 'Adaptation du sujet ENSEA AS 2024 sur l’intelligence artificielle : quelle question articule les progrès et les dangers demandés ?', options: ['Comment tirer parti des usages de l’intelligence artificielle tout en maîtrisant les risques qu’ils entraînent ?', 'Pourquoi toute technologie est-elle nécessairement parfaite ?', 'Quels sont les noms de tous les ordinateurs ?'], bonne: 0, explication: '(ENSEA AS 2024, Ordre général, sujet 1, adaptation) L’énoncé demande les rôles, les progrès possibles et les dangers de l’intelligence artificielle. La première question articule les bénéfices et leur maîtrise. Les deux autres suppriment la discussion ou changent de sujet.', miniCours: mc('Articuler les demandes', 'Une problématique doit relier les dimensions du sujet, sans en supprimer une pour faciliter artificiellement la réponse.', 'Une question qui couvre le problème.') }),
    qcm({ code: 'ENSEA-AS-OG-E08', niveau: 2, notions: ['ARGUMENTER'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Quel commentaire exploite correctement un exemple hypothétique de cours téléchargé ?', options: ['Il montre une possibilité d’accès ; il faut encore examiner la compréhension et l’usage du cours.', 'Il prouve que tous les élèves apprennent seuls.', 'Il établit un taux officiel de réussite.'], bonne: 0, explication: 'Un cours téléchargé illustre la disponibilité d’une ressource. Cela ne montre ni son apprentissage effectif ni un résultat pour tous les élèves. Aucun taux ne peut être tiré d’un cas imaginé.', miniCours: mc('La portée de l’exemple', 'Explique ce qu’un exemple montre effectivement. Ne transforme pas une illustration en preuve générale ni en statistique.', 'Conclure à la bonne échelle.') }),
    glisser({ code: 'ENSEA-AS-OG-E09', niveau: 2, notions: ['REDACTION', 'ARGUMENTER'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Complète ce paragraphe : cause, illustration puis limite.', texte: 'Le prêt peut élargir l’accès, {{car}} il évite l’achat de chaque livre. {{Par exemple}}, imaginons un élève empruntant un manuel. {{Cependant}}, la distance peut encore freiner sa fréquentation.', distracteurs: ['Donc'], explication: '« Car » explique le gain d’accès par l’économie d’achat. « Par exemple » annonce le cas imaginé. « Cependant » introduit une limite qui empêche de conclure que le prêt résout tous les obstacles.', miniCours: mc('Les liens de rédaction', 'Un connecteur doit correspondre au rôle réel de la phrase : raison, illustration, conséquence ou limite.', 'Le mot rend le raisonnement visible.') }),
    qcm({ code: 'ENSEA-AS-OG-E10', niveau: 2, notions: ['REDACTION'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Après avoir établi que l’accès numérique est utile mais dépend d’un accompagnement, quelle conclusion convient ?', options: ['Le numérique aide à apprendre lorsque les ressources sont comprises et utilisées dans un travail accompagné.', 'Nous avons d’abord parlé des avantages puis des limites.', 'Une nouvelle statistique prouve maintenant le contraire, sans développement.'], bonne: 0, explication: 'La première conclusion répond en donnant la condition tirée du devoir. La deuxième ne fait que rappeler le plan. La troisième introduit une preuve nouvelle sans l’examiner.', miniCours: mc('Répondre en conclusion', 'Reprends le résultat du raisonnement pour répondre à la question. La conclusion n’est ni une table des matières ni un nouveau développement.', 'Terminer sur une réponse fondée.') }),
    entourer({ code: 'ENSEA-AS-OG-E11', niveau: 2, notions: ['REVISION'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026' }, consigne: 'Entoure les contrôles à faire pendant la relecture du sens.', elements: [['Le développement répond à tous les aspects du sujet.', true], ['La conclusion répond à la problématique.', true], ['Le plan annoncé est effectivement suivi.', true], ['Chaque ligne contient une citation.', false]], explication: 'La réponse, la conclusion et le plan doivent être cohérents. Une citation n’est utile que si elle est exacte, pertinente et expliquée ; aucune quantité systématique n’est requise.', miniCours: mc('Relire le raisonnement', 'Compare sujet, problématique, plan, développement et conclusion avant de corriger la langue.', 'Une seule réponse cohérente.') }),
    qcm({ code: 'ENSEA-AS-OG-E12', indice: 'Identifie la relation affirmée par la citation, puis ce que demande le verbe de consigne.', niveau: 3, notions: ['SUJET', 'ARGUMENTER', 'PLAN'], source: { type: 'annale', organisme: 'INFJ', annee: 2025, epreuve: 'Magistrature — Sujet d’ordre général, sujet 3', documentId: '6ad44375dd410f0b0256bc42' }, consigne: 'Le sujet INFJ Magistrature de juillet 2025 attribue à Octavio Paz une affirmation reliant la vitalité des cultures aux rencontres et leur déclin à l’isolement. Quelle démarche répond à « Qu’en pensez-vous ? » ?', options: ['Expliquer l’apport des échanges, examiner les conditions et limites de cet apport, puis formuler une réponse argumentée.', 'Résumer uniquement la vie de l’auteur cité.', 'Approuver sans raison puisque la phrase est attribuée à un auteur.'], bonne: 0, explication: '(INFJ Magistrature 2025, Sujet d’ordre général, adaptation) La citation oppose rencontre et isolement. Il faut expliciter cette relation, montrer comment des échanges peuvent enrichir une culture et examiner leurs conditions, par exemple leur caractère réciproque. La réponse doit être justifiée ; aucune biographie n’est demandée.', miniCours: mc('Discuter une citation', 'Identifie la proposition et ses mots de portée. Examine ses raisons et ses limites avant de prendre position.', 'Une citation se discute, elle ne fait pas autorité à elle seule.') }),
    qcm({ code: 'ENSEA-AS-OG-E13', niveau: 3, notions: ['SUJET', 'ARGUMENTER'], source: { type: 'annale', organisme: 'ENS', annee: 2026, epreuve: 'Éducateur — Culture générale (Français), production écrite', documentId: '6ae6cbf211c325e41b45d6df' }, consigne: 'Adaptation de la production écrite ENS Éducateur 2026 : montrer comment le métier d’éducateur peut satisfaire la définition du travail décent donnée dans le texte. Quel axe est pertinent ?', options: ['Relier les dimensions de cette définition aux conditions concrètes d’exercice du métier, sans présumer qu’elles sont déjà toutes satisfaites.', 'Réciter tout le texte sans parler du métier.', 'Raconter seulement pourquoi on aime l’école.'], bonne: 0, explication: '(ENS Éducateur 2026, Culture générale, production écrite, adaptation) Le texte associe notamment libre choix, respect, absence de discrimination et possibilités de développement. La consigne demande un lien avec le métier visé. Il faut donc expliquer, avec des exemples, les conditions qui permettraient de réaliser ces dimensions dans ce métier.', miniCours: mc('Répondre à une application', 'Quand la consigne demande d’appliquer une définition à un métier, relève ses critères puis justifie leur lien avec les conditions d’exercice.', 'Définition, critères, application expliquée.') }),
    qcm({ code: 'ENSEA-AS-OG-E14', indice: 'Compare la copie à chaque dimension de la consigne, pas seulement à son introduction.', niveau: 3, notions: ['SUJET', 'PLAN', 'REVISION'], source: { type: 'original', inspireDe: 'ENSEA AS 2025 — Ordre général' }, consigne: 'Une copie sur l’accès équitable à l’eau traite seulement les gestes domestiques alors que le sujet demande aussi une gestion entre pays. Quelle réparation est prioritaire ?', options: ['Ajouter une étape argumentée sur la coopération entre pays et ajuster l’annonce et la conclusion.', 'Supprimer le mot international de l’introduction et garder le reste.', 'Multiplier les adjectifs sur les gestes domestiques.'], bonne: 0, explication: 'Le défaut concerne une dimension du sujet, pas un mot isolé de l’introduction. Il faut rétablir l’échelle omise avec des arguments pertinents, puis rendre l’annonce et la conclusion cohérentes avec le développement réparé.', miniCours: mc('Réparer un hors-sujet partiel', 'Compare la copie à toutes les demandes du sujet. Une dimension absente exige une correction du raisonnement.', 'La consigne reste la référence.') }),
    vf({ code: 'ENSEA-AS-OG-E15', niveau: 3, notions: ['PLAN', 'REDACTION', 'REVISION'], source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025' }, consigne: 'Évalue ces choix pour une copie de concours.', affirmations: [['Un plan doit répondre au sujet même s’il diffère d’un modèle appris.', true], ['Un exemple hypothétique doit être présenté comme un fait officiel.', false], ['Une conclusion peut formuler une réponse conditionnelle si le développement l’a justifiée.', true], ['Il faut toujours afficher les titres du brouillon dans une copie ENSEA.', false]], explication: 'Le sujet détermine le plan. Un cas inventé doit être annoncé comme hypothétique. Une conclusion conditionnelle est valable si ses conditions sont démontrées. Enfin, le jury ENSEA 2026 demande un devoir rédigé sans titres de parties apparents : les transitions rendent la progression lisible.', miniCours: mc('Adapter la forme et le fond', 'Un devoir justifie une réponse et respecte les consignes propres au concours. Un modèle de brouillon ne devient pas automatiquement la forme de la copie.', 'Pertinence et cohérence avant les automatismes.') }),
  ],
};

// Dossier entièrement inventé : aucun de ces documents n’est une norme en vigueur.
const dossierAccueil = 'DOSSIER FICTIF D’ENTRAÎNEMENT — D1, charte interne 2024 : information gratuite et maintien d’un accueil physique. D2, bilan interne 2025 : les démarches en ligne réduisent certains déplacements, mais des usagers manquent d’équipement. D3, avis associatif 2025 : l’accompagnement est insuffisant ; une aide humaine est proposée. D4, projet 2026 : une permanence mobile est envisagée à titre expérimental ; aucune mise en œuvre n’est annoncée.';

const synthese = {
  code: 'INFJ-MAG-SYNTHESE', matiere: 'Culture générale',
  titre: 'Dissertation et note de synthèse',
  resume: 'Distinguer les tâches, exploiter un dossier sans ajout et exercer un raisonnement précis en culture générale et juridique.',
  notions: [
    { code: 'COMMANDE', libelle: 'Dissertation, résumé ou note : identifier la tâche' },
    { code: 'DOSSIER', libelle: 'Nature, date, auteur et portée des documents' },
    { code: 'CROISER', libelle: 'Sélection et confrontation des informations' },
    { code: 'PLAN-NOTE', libelle: 'Plan thématique de synthèse' },
    { code: 'NEUTRALITE', libelle: 'Rédaction neutre, attribution et traçabilité' },
    { code: 'PRECISION', libelle: 'Faits, opinions, règles et limites des affirmations' },
    { code: 'CONTROLE', libelle: 'Note complète, gestion du temps et vérification' },
  ],
  lecons: [
    lecon('INFJ-MAG-SYNTHESE-L1', 'Identifier ce que la copie doit produire', 3, [
      b.texte('Tu vas distinguer trois travaux pour choisir la bonne méthode. Pour apprendre la dissertation depuis le début, suis d’abord **ENSEA-AS-OG**, ajouté avant ce module dans le programme. Il enseigne une seule fois l’analyse du sujet, la problématique et la rédaction.'),
      b.tableau(['Travail demandé', 'Matière de la réponse'], [['Résumé', 'Réduire fidèlement un texte en suivant son parcours.'], ['Dissertation', 'Répondre avec des arguments et des connaissances pertinents.'], ['Note de synthèse', 'Organiser les informations utiles d’un dossier sans apport personnel.']]),
      b.texte('Un **dossier** est un ensemble de documents réunis pour traiter un sujet. **Synthétiser**, c’est rapprocher leurs informations pour produire une présentation d’ensemble. La consigne précise le thème, la longueur, le destinataire éventuel et la forme attendue.'),
      b.exemple('Deux commandes différentes', '« Discutez la place du numérique dans l’accès aux services » appelle une argumentation. « À partir des seuls documents, présentez les conditions d’accès aux services » appelle une synthèse limitée au dossier.'),
      b.piege('La page officielle des matières INFJ mentionne « SOG ou note de synthèse » en magistrature. Elle ne fixe pas ici un format détaillé daté pour chaque session. Vérifie donc l’avis et la consigne avant d’appliquer une longueur ou une présentation apprise ailleurs.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L1-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['COMMANDE'], consigne: 'La commande impose les seuls documents du dossier. Peut-on ajouter une statistique apprise ailleurs ?', options: ['Non : elle est extérieure au dossier.', 'Oui, si elle paraît intéressante.', 'Oui, sans citer sa provenance.'], bonne: 0, explication: 'La limite « seuls documents » exclut les connaissances extérieures, même pertinentes. La note organise les informations disponibles au lieu d’enrichir le dossier.', miniCours: mc('Identifier la tâche', 'Le périmètre des sources dépend de la commande. Dans une synthèse stricte, les documents constituent toute la matière de la copie.', 'Respecter la commande.') })),
      b.recap(['Lire la commande complète.', 'Distinguer argumentation et restitution de dossier.', 'Appliquer le format de la session.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L2', 'Faire la carte des documents', 4, [
      b.texte('Tu vas repérer les documents avant de prendre des notes détaillées. Pour chacun, relève son auteur ou institution, sa date, sa **nature** et sa question principale. La nature indique le type : règle, bilan, opinion, décision ou projet.'),
      b.texte('Une **règle** énonce ce qui est permis, interdit ou demandé dans un cadre donné. Un bilan décrit une situation ; un avis exprime un jugement ; un projet présente une mesure envisagée. Ils ne disent donc pas la même chose et n’ont pas la même portée.'),
      b.exemple('Petit dossier entièrement fictif', dossierAccueil),
      b.exemple('Une première carte', 'D1 fixe ici une orientation interne ; D2 décrit des effets et obstacles ; D3 porte un jugement et une proposition ; D4 envisage une expérience future. Aucun de ces documents inventés n’établit une règle de droit réelle.'),
      b.piege('Le document le plus récent n’annule pas automatiquement les plus anciens. Un projet récent n’est pas une règle appliquée. Vérifie les indications de statut et de champ au lieu de déduire la suppression d’une règle de la seule date.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L2-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['DOSSIER'], consigne: 'Dans D4, la permanence mobile est…', options: ['Un projet expérimental, sans mise en œuvre annoncée', 'Une mesure déjà généralisée', 'Une loi nationale en vigueur'], bonne: 0, explication: 'D4 emploie « envisagée » et ne signale aucune mise en œuvre. Il faut conserver ce statut de projet ; la date seule n’établit aucun changement effectif.', miniCours: mc('Nature et statut', 'Distingue ce qui est constaté, demandé, jugé ou seulement envisagé.', 'Lire le statut avant de conclure.') })),
      b.recap(['Identifier auteur, date et nature.', 'Distinguer constat, avis et projet.', 'Ne pas attribuer une portée absente du document.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L3', 'Prendre des notes utiles et traçables', 4, [
      b.texte('Tu vas sélectionner les informations utiles sans recopier chaque page. Une information est **pertinente** si elle aide à répondre au thème précis de la commande. Elle est **traçable** si tu sais dans quel document la retrouver.'),
      b.texte('Après la première carte, choisis un ordre de lecture qui aide à comprendre le dossier : un document de présentation peut éclairer les textes plus techniques. Lis ensuite tous les documents. Pour chaque note, garde une idée brève, sa référence et son statut.'),
      b.exemple('Commande d’entraînement', '« Présentez, à partir du dossier fictif de L2, les acquis, obstacles et réponses envisagées pour l’accès au service. » D2 : certains déplacements diminuent grâce aux démarches en ligne ; obstacle : manque d’équipement. Ces deux notes répondent à la commande.'),
      b.tableau(['Note au brouillon', 'Référence et statut'], [['Maintien du guichet et gratuité', 'D1 — orientation interne'], ['Besoin d’aide humaine', 'D3 — proposition associative'], ['Permanence mobile possible', 'D4 — projet expérimental']]),
      b.piege('« Tout le monde est satisfait » ne peut pas remplacer une note sur des déplacements réduits : tu ajouterais une généralisation. Conserve aussi les réserves et les conditions.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L3-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['DOSSIER', 'CROISER'], consigne: 'Quelle note reste fidèle à D2 ?', options: ['D2 : certains déplacements diminuent, mais l’équipement manque à des usagers.', 'D2 : le numérique résout tous les problèmes.', 'D2 : le guichet doit être fermé.'], bonne: 0, explication: 'La première note conserve le bénéfice et la limite décrits. Les deux autres inventent soit une réussite générale, soit une décision de fermeture.', miniCours: mc('Noter sans déformer', 'Une note courte conserve l’idée, sa portée et sa référence documentaire.', 'Court et vérifiable.') })),
      b.recap(['Lire tous les documents.', 'Sélectionner selon la commande.', 'Noter l’idée, sa limite et sa référence.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L4', 'Croiser les documents au lieu de les empiler', 4, [
      b.texte('Tu vas rapprocher les notes sur une même question. **Croiser** les documents, c’est identifier leurs accords, leurs compléments ou leurs divergences. Un désaccord doit être décrit, pas tranché selon ton opinion.'),
      b.texte('Crée des groupes thématiques : principes d’accès, obstacles, réponses. Place chaque note dans le groupe utile avec son numéro de document. Un document peut apporter des éléments à plusieurs groupes.'),
      b.exemple('Un complément', 'Dans le dossier fictif de L2, D2 signale un manque d’équipement ; D3 propose une aide humaine. La seconde information répond à une difficulté liée à l’usage, sans prouver que tout le manque d’équipement disparaîtra.'),
      b.exemple('Une tension à conserver', 'D1 maintient un accueil physique, mais D3 juge l’accompagnement insuffisant. Un engagement d’accès et un jugement sur sa réalisation peuvent coexister : la note expose cette différence sans accuser ni approuver.'),
      b.piege('Deux documents qui utilisent le mot « accès » ne disent pas forcément la même chose. Vérifie le public, le service, la date et l’indicateur avant de conclure à un accord ou une contradiction.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L4-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['CROISER'], consigne: 'Quelle phrase croise fidèlement D1 et D3 ?', options: ['La charte maintient l’accueil physique, tandis que l’avis associatif souligne une insuffisance d’accompagnement.', 'La charte prouve que tout accompagnement est suffisant.', 'L’avis associatif supprime la charte.'], bonne: 0, explication: 'La première phrase distingue l’orientation de D1 et le jugement de D3. Rien ne prouve que l’accueil répond à tous les besoins ; un avis ne supprime pas à lui seul une orientation interne.', miniCours: mc('Mettre en relation', 'Compare le contenu et la portée des documents. Conserve une tension si le dossier la présente.', 'Rapprocher sans confondre.') })),
      b.recap(['Regrouper les informations par question.', 'Faire apparaître compléments et tensions.', 'Conserver les attributions et les limites.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L5', 'Construire le plan de la note', 4, [
      b.texte('Tu vas organiser les informations pour un lecteur qui ne connaît pas le dossier. Le plan de synthèse suit les questions communes aux documents, plutôt que leur ordre matériel.'),
      b.texte('Pour chaque groupe de notes, formule un titre précis. Vérifie ensuite que chaque information importante a une place et que chaque partie repose sur le dossier. Un plan en deux parties est un outil possible, pas une obligation générale de l’INFJ vérifiée pour toute session.'),
      b.exemple('Plan pour le dossier fictif', 'Commande : présenter acquis, obstacles et réponses envisagées. I. Des modalités d’accès élargies, encore limitées par des obstacles matériels et humains (D1, D2, D3). II. Des réponses d’accompagnement proposées ou envisagées (D3, D4).'),
      b.exemple('Vérifier les titres', '« Documents 1 et 2 / Documents 3 et 4 » énumère les pièces. « Accès élargi mais encore inégal / Réponses d’accompagnement » exprime leur contenu et la relation entre les informations.'),
      b.piege('N’utilise pas une partie « Mes solutions » si la commande demande uniquement une synthèse. Tu peux présenter les solutions proposées dans les documents, en les attribuant.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L5-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['PLAN-NOTE'], consigne: 'Quel plan correspond à une synthèse stricte du dossier fictif ?', options: ['Acquis et obstacles d’accès / Réponses proposées dans le dossier', 'Résumé de D1 / Résumé de D2 / Résumé de D3 / Résumé de D4', 'Mon avis / Mes réformes personnelles'], bonne: 0, explication: 'Le premier plan regroupe les informations selon les questions de la commande. Le deuxième reste une succession de résumés ; le troisième introduit une opinion et des apports extérieurs.', miniCours: mc('Un plan de synthèse', 'Organise le dossier autour de ses questions communes. Les parties doivent aider le lecteur à comprendre l’ensemble.', 'Des thèmes documentés, pas une liste de pièces.') })),
      b.recap(['Partir des questions du dossier.', 'Choisir des titres informatifs.', 'Vérifier la couverture sans apport personnel.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L6', 'Rédiger une synthèse neutre', 4, [
      b.texte('Tu vas **reformuler**, c’est-à-dire exprimer les informations avec tes phrases, et rester **neutre**, sans approuver ni condamner les positions du dossier. La copie doit faire comprendre leur articulation.'),
      b.texte('Présente brièvement l’objet et les axes de la note. Dans les paragraphes, rapproche les documents en précisant les attributions utiles. Pour cet entraînement, les références D1, D2… assurent la traçabilité ; dans une épreuve, suis la convention demandée. Les titres peuvent rendre le plan visible si le format l’autorise.'),
      b.exemple('Une phrase fidèle', '« Le bilan relève une réduction de certains déplacements grâce aux démarches en ligne, mais signale aussi un défaut d’équipement (D2). L’avis associatif propose un accompagnement humain (D3). » Les constats et la proposition restent distingués.'),
      b.exemple('Un projet reste un projet', '« Une permanence mobile est envisagée à titre expérimental (D4). » Écrire « La permanence mobile résout désormais la difficulté » transformerait un projet en résultat établi.'),
      b.piege('Évite les adjectifs comme « scandaleux » ou « excellent » qui ajoutent ton jugement. Si un document emploie un jugement, attribue-le clairement plutôt que de le reprendre à ton compte.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L6-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['NEUTRALITE'], consigne: 'Quelle formulation reste neutre ?', options: ['L’association estime l’accompagnement insuffisant et propose une aide humaine (D3).', 'L’association a évidemment raison.', 'Le service est scandaleusement inutile.'], bonne: 0, explication: 'La première formule attribue le jugement à son auteur et restitue sa proposition. Les deux autres ajoutent l’approbation ou la condamnation du rédacteur.', miniCours: mc('Attribuer un jugement', 'La neutralité n’efface pas les opinions du dossier : elle permet de les présenter sans les adopter.', 'Exposer sans juger.') })),
      b.recap(['Reformuler sans modifier la portée.', 'Attribuer constats, opinions et projets.', 'Respecter les conventions de présentation de l’épreuve.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L7', 'Raisonner avec précision en culture générale et juridique', 4, [
      b.texte('Tu vas adapter le socle **ENSEA-AS-OG-L2 à L8** aux sujets proches de la justice. Rappel : analyse les termes, formule la difficulté, organise des arguments, puis conclus. Ces habitudes de précision sont des choix de préparation ; elles ne constituent pas un barème officiel INFJ.'),
      b.texte('Distingue un **fait**, présenté comme constat, une **opinion**, jugement discutable, et une **règle**, énoncé qui prescrit dans un cadre donné. Le **droit en vigueur** désigne les règles applicables à un lieu et une date ; une réforme souhaitée n’en fait pas partie par le seul fait qu’elle est proposée.'),
      b.exemple('Ne pas changer de tâche', 'Un sujet général sur le dialogue entre cultures demande d’examiner des échanges, leurs effets et leurs limites. Ajouter des articles de loi sans lien ne rend pas la réponse plus pertinente. Utilise la méthode de discussion des citations du socle commun.'),
      b.exemple('Justifier une affirmation juridique', 'Dans un sujet portant réellement sur une règle, identifie sa source, son champ, ses conditions et ses exceptions avant de l’utiliser. Si tu ne peux pas garantir un numéro d’article, ne l’invente pas. Ne déduis pas d’une règle interne fictive de L2 une obligation nationale réelle.'),
      b.piege('« Je souhaite que cette mesure existe » et « cette mesure s’applique » sont deux affirmations différentes. Dans une dissertation, une proposition personnelle peut être argumentée ; dans une note stricte, seuls les projets du dossier sont restitués.'),
      b.question(classer({ code: 'INFJ-MAG-SYNTHESE-L7-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 1, notions: ['PRECISION'], consigne: 'Classe ces énoncés fictifs par nature.', categories: ['Constat', 'Opinion', 'Règle interne'], cartes: [['Le bilan relève un manque d’équipement.', 0], ['L’association juge l’aide insuffisante.', 1], ['La charte prescrit le maintien du guichet.', 2]], explication: 'Le bilan décrit une situation. L’avis porte une appréciation. La charte prescrit une conduite dans son cadre interne fictif. Ces trois énoncés ne sont pas interchangeables.', miniCours: mc('Qualifier un énoncé', 'Repère si le texte décrit, juge ou prescrit, puis conserve sa portée.', 'Nature et champ avant emploi.') })),
      b.recap(['Réutiliser le socle de dissertation.', 'Distinguer faits, opinions et règles.', 'Vérifier le cadre et ne pas inventer de référence.']),
    ]),
    lecon('INFJ-MAG-SYNTHESE-L8', 'Achever et contrôler une note complète', 4, [
      b.texte('Tu vas vérifier le résultat complet sur le dossier fictif de L2. Commande d’entraînement : « Présentez les acquis, obstacles et réponses envisagées. Utilisez deux parties titrées, des références D1–D4, sans avis ni conclusion séparée. » Ce format est propre à cet entraînement.'),
      b.exemple('Introduction et première partie possibles', '« Le dossier présente un accès au service élargi mais encore contraint, puis des réponses d’accompagnement. I. Un accès élargi, encore limité. La charte prévoit la gratuité de l’information et le maintien de l’accueil physique (D1). Les démarches en ligne réduisent certains déplacements, mais le manque d’équipement demeure un obstacle (D2). L’association juge aussi l’accompagnement insuffisant (D3). »'),
      b.exemple('Seconde partie possible', '« II. Des réponses d’accompagnement proposées. L’avis associatif préconise une aide humaine (D3). Un projet envisage une permanence mobile expérimentale, sans annoncer sa mise en œuvre (D4). » Chaque information est retrouvable dans le dossier ; aucun effet futur n’est présenté comme acquis.'),
      b.liste(['Contrôler la commande : tous les aspects demandés et la forme attendue.', 'Vérifier chaque affirmation dans les documents : source, statut, limites.', 'Relire les titres, enchaînements, accords et références ; contrôler la longueur imposée.'], true),
      b.texte('Pour une séance d’entraînement de 4 h : 15 min de commande et repérage, 75 min de lecture et notes, 30 min de regroupement et plan, 100 min de rédaction, 20 min de relecture. Total : 240 min. Ajuste après un essai ; ce partage n’est pas une prescription INFJ.'),
      b.piege('Ne généralise pas l’absence de conclusion de cet entraînement : la fin de note, les titres et les références dépendent du format demandé. N’ajoute jamais une ouverture personnelle à une synthèse stricte.'),
      b.question(qcm({ code: 'INFJ-MAG-SYNTHESE-L8-Q1', source: { type: 'original', inspireDe: 'ENSEA AS 2024–2026 ; INFJ Magistrature 2025 ; méthode de dossier' }, niveau: 2, notions: ['CONTROLE', 'NEUTRALITE'], consigne: 'La copie affirme que D4 a déjà réglé les difficultés. Quelle réparation convient ?', options: ['Rétablir le statut de projet et supprimer le résultat non attesté.', 'Garder la phrase pour rendre la note optimiste.', 'Ajouter un avis personnel pour la justifier.'], bonne: 0, explication: 'D4 ne décrit ni mise en œuvre ni résultat. Il faut revenir à la mesure envisagée et retirer l’effet inventé, puis relire l’ensemble pour vérifier sa cohérence.', miniCours: mc('Le contrôle final', 'Toute affirmation d’une note doit être appuyée par le dossier et respecter la portée du document.', 'Vérifier ce qui est réellement attesté.') })),
      b.recap(['Achever une réponse à toute la commande.', 'Vérifier source et portée de chaque phrase.', 'Respecter le format et garder un temps de relecture.']),
    ]),
  ],
  exercices: [
    relier({ code: 'INFJ-MAG-SYNTHESE-E01', niveau: 1, notions: ['COMMANDE'], source: { type: 'original', inspireDe: 'INFJ Magistrature 2025 ; méthode de synthèse documentaire' }, consigne: 'Relie la commande au travail attendu.', paires: [['Réduisez ce texte en 100 mots', 'Résumé fidèle d’un texte'], ['Discutez une affirmation à l’aide d’arguments', 'Dissertation'], ['Présentez les informations des seuls documents joints', 'Note de synthèse stricte']], explication: 'La réduction d’un texte correspond au résumé. La discussion justifiée d’une affirmation correspond à la dissertation. La présentation organisée à partir des seuls documents limite la matière au dossier : c’est la synthèse.', miniCours: mc('Trois tâches', 'Le résumé suit un texte, la dissertation argumente, la note rapproche des documents. La consigne fixe le périmètre.', 'Identifier avant de rédiger.') }),
    classer({ code: 'INFJ-MAG-SYNTHESE-E02', niveau: 1, notions: ['DOSSIER'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, consigne: 'Dossier entièrement fictif : classe ces pièces par nature.', categories: ['Règle interne', 'Constat', 'Avis', 'Projet'], cartes: [['D1 : la charte prévoit le maintien de l’accueil physique.', 0], ['D2 : le bilan relève un manque d’équipement.', 1], ['D3 : l’association juge l’aide insuffisante.', 2], ['D4 : une permanence est envisagée.', 3]], explication: 'D1 prescrit une orientation interne ; D2 décrit une difficulté ; D3 évalue l’accompagnement ; D4 envisage une action future. Aucun de ces statuts ne peut remplacer les autres dans une synthèse.', miniCours: mc('La nature documentaire', 'Repère si la pièce prescrit, décrit, juge ou propose. La nature aide à formuler une restitution exacte.', 'Qualifier avant de rapprocher.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E03', niveau: 1, notions: ['DOSSIER', 'PRECISION'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Que permet d’affirmer D4 ?', options: ['Une permanence mobile est envisagée à titre expérimental.', 'La permanence est déjà généralisée.', 'La charte D1 est automatiquement supprimée.'], bonne: 0, explication: 'Le mot « envisagée » marque un projet. D4 ne fournit ni mise en œuvre, ni généralisation, ni suppression de D1. Sa date récente ne permet donc pas ces conclusions.', miniCours: mc('La date ne suffit pas', 'Le statut, le champ et les indications de mise en œuvre comptent autant que la date.', 'Un projet reste un projet.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E04', niveau: 1, notions: ['CROISER'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Quelle note de brouillon est exacte et traçable ?', options: ['D2 : baisse de certains déplacements, avec un obstacle d’équipement pour des usagers.', 'D2 : satisfaction générale prouvée.', 'D3 : loi nationale de gratuité.'], bonne: 0, explication: 'La première note garde le bénéfice limité, l’obstacle et le numéro de pièce. D2 ne mesure pas une satisfaction générale ; D3 est un avis associatif, pas une loi.', miniCours: mc('Une note utile', 'Note une information pertinente avec sa référence et ses limites. Une reformulation brève ne doit pas ajouter de résultat.', 'Idée, portée, document.') }),
    entourer({ code: 'INFJ-MAG-SYNTHESE-E05', niveau: 1, notions: ['DOSSIER'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, consigne: 'Entoure les informations à relever pour identifier un document.', elements: [['Son auteur ou institution', true], ['Sa date', true], ['Sa nature et son statut', true], ['L’opinion personnelle du candidat sur son auteur', false]], explication: 'L’auteur aide à attribuer le propos, la date à le situer, la nature et le statut à savoir s’il décrit, prescrit ou propose. L’opinion du candidat ne sert pas à identifier la pièce et n’entre pas dans une synthèse stricte.', miniCours: mc('La carte du dossier', 'Repère l’origine, la date et la nature de chaque pièce avant la lecture détaillée.', 'Identifier pour restituer exactement.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E06', niveau: 2, notions: ['CROISER', 'NEUTRALITE'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Quelle phrase rapproche D2 et D3 sans exagération ?', options: ['Le manque d’équipement relevé par le bilan accompagne un besoin d’aide humaine souligné par l’association.', 'L’association prouve que tous les usagers rejettent le numérique.', 'Le bilan affirme que l’aide humaine est interdite.'], bonne: 0, explication: 'La première phrase rapproche deux obstacles tout en gardant leurs sources. D3 ne prouve pas un rejet unanime ; D2 ne présente aucune interdiction d’aide. Il faut exposer le rapprochement sans inventer une conclusion générale.', miniCours: mc('Croiser', 'Mettre en relation des pièces ne permet pas d’élargir leurs affirmations au-delà de ce qu’elles attestent.', 'Relier et conserver les limites.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E07', niveau: 2, notions: ['PLAN-NOTE', 'CROISER'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Commande : présenter acquis, obstacles et réponses envisagées. Quel plan couvre le dossier ?', options: ['I. Accès élargi et obstacles persistants ; II. Accompagnements proposés ou envisagés', 'I. D1 seulement ; II. Mon expérience personnelle', 'I. Histoire du service ; II. Propositions absentes des documents'], bonne: 0, explication: 'La première partie permet de traiter D1, D2 et le constat de D3. La seconde regroupe la proposition de D3 et le projet de D4. Les autres plans omettent des pièces et ajoutent des éléments étrangers à la commande.', miniCours: mc('Plan et couverture', 'Vérifie que chaque aspect demandé et chaque information essentielle trouvent une place dans les parties.', 'Organiser le dossier entier.') }),
    glisser({ code: 'INFJ-MAG-SYNTHESE-E08', niveau: 2, notions: ['NEUTRALITE', 'PRECISION'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, consigne: `${dossierAccueil}\nComplète en respectant le statut de chaque pièce.`, texte: 'Le bilan {{constate}} une difficulté d’équipement (D2). L’association {{juge}} l’aide insuffisante (D3). Le projet {{envisage}} une permanence mobile (D4).', distracteurs: ['abroge', 'garantit définitivement'], explication: 'Un bilan constate ici une situation ; l’avis porte un jugement ; le projet envisage une action. Aucun de ces énoncés ne supprime une règle ni ne garantit un résultat définitif.', miniCours: mc('Des verbes précis', 'Choisis le verbe selon la nature du document et son contenu. Une proposition et un résultat établi ne se présentent pas de la même manière.', 'Le verbe indique la portée.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E09', niveau: 2, notions: ['NEUTRALITE'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Quelle phrase peut figurer dans une note neutre ?', options: ['L’avis associatif estime l’accompagnement insuffisant et préconise une aide humaine (D3).', 'Je suis convaincu que D3 est excellent.', 'D3 a scandaleusement raison.'], bonne: 0, explication: 'La première phrase restitue une appréciation et une proposition en les attribuant à l’avis. Les autres ajoutent l’approbation et les jugements de valeur du candidat, absents du dossier.', miniCours: mc('Neutralité', 'Une opinion du dossier peut être exposée avec une attribution. Elle ne devient pas pour autant la position du rédacteur.', 'Attribuer sans approuver.') }),
    vf({ code: 'INFJ-MAG-SYNTHESE-E10', niveau: 2, notions: ['PRECISION', 'COMMANDE'], source: { type: 'original', inspireDe: 'INFJ Magistrature 2025 ; entraînement méthodologique' }, consigne: 'Juge ces pratiques de précision.', affirmations: [['Une réforme souhaitée est distincte d’une règle applicable.', true], ['On peut inventer un numéro d’article pour paraître précis.', false], ['Un sujet de culture générale doit être remplacé par une récitation juridique.', false], ['Une règle doit être replacée dans son champ et ses conditions avant d’être utilisée.', true]], explication: 'Une proposition n’est pas une règle en vigueur. Une référence inventée est inexacte ; mieux vaut s’en tenir à ce qu’on peut établir. Le sujet demeure la référence, même dans un concours judiciaire. Une règle n’appuie un raisonnement qu’en respectant son domaine et ses conditions.', miniCours: mc('La précision utile', 'Distingue constats, jugements et prescriptions. Utilise une référence seulement si son contenu et son cadre sont fiables.', 'Ne pas inventer d’autorité.') }),
    surligner({ code: 'INFJ-MAG-SYNTHESE-E11', indice: 'Pour chaque résultat annoncé, cherche la pièce qui atteste sa réalisation.', niveau: 3, notions: ['NEUTRALITE', 'CONTROLE'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, consigne: `${dossierAccueil}\nSurligne les deux affirmations non appuyées par ce dossier.`, segments: [['Le bilan relève une diminution de certains déplacements. ', false], ['Tous les usagers disposent désormais d’un équipement. ', true], ['Une permanence mobile est envisagée. ', false], ['Elle a déjà supprimé toutes les difficultés.', true]], explication: 'D2 signale au contraire un manque d’équipement pour des usagers : la généralisation est fausse. D4 décrit un projet sans mise en œuvre ; aucun résultat ne peut donc lui être attribué. Les deux autres phrases conservent les informations du bilan et du projet.', miniCours: mc('Traquer les ajouts', 'Vérifie chaque quantificateur et chaque résultat annoncé. Le dossier doit appuyer toute affirmation de la note.', 'Attention à « tous » et « déjà ».') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E12', niveau: 3, notions: ['COMMANDE', 'PRECISION'], source: { type: 'annale', organisme: 'INFJ', annee: 2025, epreuve: 'Magistrature — Sujet d’ordre général, sujet 3', documentId: '6ad44375dd410f0b0256bc42' }, consigne: 'Le scan INFJ Magistrature juillet 2025 présente une citation sur rencontres et vitalité des cultures, suivie de « Qu’en pensez-vous ? », sans dossier joint. Quelle préparation choisir ?', options: ['Le socle de dissertation ENSEA-AS-OG : analyse, arguments, limites, plan puis réponse rédigée.', 'Une note limitée à des documents inexistants.', 'Une liste d’articles de droit sans rapport avec les cultures.'], bonne: 0, explication: '(INFJ Magistrature 2025, Sujet d’ordre général, adaptation) Le document demande une discussion de citation, pas une synthèse de pièces. On réutilise le socle commun pour expliquer la proposition, examiner des raisons et des limites, puis construire une réponse. Le contexte judiciaire du concours ne change pas la consigne.', miniCours: mc('Choisir la méthode', 'Le type d’exercice vient de la commande et des matériaux fournis. Un concours judiciaire peut proposer une réflexion de culture générale.', 'La consigne prime.') }),
    qcm({ code: 'INFJ-MAG-SYNTHESE-E13', indice: 'Vérifie successivement la présence et le statut de D1, D2, D3 et D4.', niveau: 3, notions: ['NEUTRALITE', 'PLAN-NOTE', 'CONTROLE'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, enonce: dossierAccueil, consigne: 'Quelle mini-synthèse restitue tout le dossier sans avis ni effet inventé ?', options: ['La charte associe gratuité et maintien de l’accueil physique (D1). Le numérique réduit certains déplacements, malgré un obstacle d’équipement (D2). L’association propose une aide humaine face à un accompagnement jugé insuffisant (D3). Une permanence mobile expérimentale est envisagée, sans mise en œuvre annoncée (D4).', 'Le numérique suffit et tous les obstacles ont disparu.', 'La charte est inutile ; il faut la supprimer et remplacer le service par mon projet personnel.'], bonne: 0, explication: 'La première version couvre les quatre pièces : principes, bénéfice limité, obstacle, avis et projet. Elle distingue les statuts et n’annonce aucun résultat futur. La deuxième contredit les obstacles ; la troisième ajoute un jugement et une réforme personnelle.', miniCours: mc('Une synthèse complète', 'Rapproche les informations essentielles en gardant leurs attributions, leurs relations et leur degré de réalisation.', 'Tout l’utile, aucun ajout.') }),
    ordre({ code: 'INFJ-MAG-SYNTHESE-E14', niveau: 3, notions: ['COMMANDE', 'CROISER', 'PLAN-NOTE', 'CONTROLE'], source: { type: 'original', inspireDe: 'Méthode de dossier ; entraînement spécifique du module INFJ' }, mode: 'exact', consigne: 'Ordonne un cycle complet de travail sur dossier.', elements: ['Lire la commande et repérer toutes les pièces', 'Lire les documents et noter les informations utiles avec leurs références', 'Croiser les notes et bâtir un plan qui couvre la commande', 'Rédiger une présentation neutre, fidèle et reliée', 'Vérifier les sources, les statuts, la couverture et la forme finale'], explication: 'La commande donne le cap ; le repérage et la lecture fournissent la matière. Le croisement précède le plan et la rédaction. Le contrôle final compare les phrases aux pièces puis vérifie la réponse et la forme demandée.', miniCours: mc('Achever la note', 'Réserve du temps à la lecture, à l’organisation, à la rédaction et à une vérification finale. Ajuste leur durée après un entraînement.', 'Lire, rapprocher, rédiger, vérifier.') }),
  ],
};

module.exports = [dissertation, synthese];
